"use client";

import { useState } from "react";

type SingerVideoCarouselProps = {
  videos: readonly string[];
};

function getYouTubeId(videoUrl: string) {
  return new URL(videoUrl).searchParams.get("v");
}

export function SingerVideoCarousel({ videos }: SingerVideoCarouselProps) {
  const [playingVideoId, setPlayingVideoId] = useState<string | null>(null);

  return (
    <section className="am-singer-videos" aria-label="Alain Martinos singing videos">
      <p className="am-singer-swipe-hint" aria-hidden="true">
        ← Swipe left or right for more videos →
      </p>

      <div className="am-singer-video-track" tabIndex={0}>
        {videos.map((videoUrl, index) => {
          const videoId = getYouTubeId(videoUrl);

          if (!videoId) return null;

          const isPlaying = playingVideoId === videoId;

          return (
            <div key={videoId} className="am-singer-video-card">
              {isPlaying ? (
                <iframe
                  src={`https://www.youtube-nocookie.com/embed/${videoId}?autoplay=1&rel=0`}
                  title={`Alain Martinos singing video ${index + 1}`}
                  className="am-singer-player"
                  allow="autoplay; encrypted-media; picture-in-picture"
                  allowFullScreen
                />
              ) : (
                <button
                  type="button"
                  className="am-singer-video-button"
                  onClick={() => setPlayingVideoId(videoId)}
                  aria-label={`Play Alain Martinos singing video ${index + 1}`}
                >
                  <img
                    src={`https://i.ytimg.com/vi/${videoId}/hqdefault.jpg`}
                    alt={`Alain Martinos singing — video ${index + 1}`}
                    className="am-singer-thumbnail"
                    loading="lazy"
                  />
                  <span className="am-singer-play" aria-hidden="true">▶</span>
                </button>
              )}
            </div>
          );
        })}
      </div>
    </section>
  );
}
